<template>
  <main class="pos-page">
    <header class="pos-header">
      <div><p class="pos-kicker">BEGPHARMA <span>·</span> ESPACE OFFICINE</p><h1>Comptoir <em>&</em> caisse</h1><p class="pos-subtitle">Vente au comptoir, avec traçabilité des lots FEFO.</p></div>
      <div class="header-status"><span class="live-dot"/>API <strong>{{ apiState }}</strong><span class="receipt-note">Reçu interne · non fiscal</span></div>
    </header>
    <p v-if="error" class="pos-alert" role="alert">{{ error }}</p><p v-if="notice" class="pos-notice" role="status">{{ notice }}</p>
    <section class="session-band" aria-labelledby="session-title">
      <div class="session-mark"><span>01</span><div><p class="pos-kicker">ESPACE DE TRAVAIL</p><h2 id="session-title">Session de caisse</h2></div></div>
      <div class="session-facts"><div><small>ÉTAT</small><strong><i :class="session?'is-open':'is-closed'"/>{{session?'Ouverte':'Fermée'}}</strong></div><div><small>FOND DE CAISSE</small><strong>{{session?money(session.opening_cash):'—'}}</strong></div><div><small>VENTES ESPÈCES</small><strong>{{session?money(session.cash_sales):'—'}}</strong></div></div>
      <button v-if="!session&&permissions.canManageSession" class="pos-button primary" @click="prepareSession('open')">Ouvrir la caisse <span>→</span></button><button v-else-if="session&&permissions.canManageSession" class="pos-button outlined" @click="prepareSession('close')">Clôturer la caisse <span>→</span></button>
    </section>
    <section class="workspace">
      <div class="sale-panel">
        <div class="sale-heading"><div><p class="pos-kicker">02 / ENCAISSEMENT</p><h2>Vente au comptoir</h2></div><button v-if="permissions.canSell" class="pos-button primary" :disabled="!session||!!catalogError" @click="startSale">＋ Nouvelle vente</button></div>
        <div class="sale-body">
          <div class="cart-symbol" aria-hidden="true">＋</div><h3>{{session?'Prêt pour la prochaine vente':'La caisse est fermée'}}</h3>
          <p>{{session?'Recherchez un produit ou scannez son code pour commencer.':'Ouvrez une session de caisse avant d’enregistrer une vente.'}}</p>
          <button v-if="permissions.canSell" class="pos-button dark" :disabled="!session||!!catalogError" @click="startSale">Créer une vente <span>→</span></button>
          <p v-if="catalogError" class="permission-error" role="alert">Catalogue indisponible ou accès caisse.read refusé : {{catalogError}}</p>
        </div>
        <footer class="sale-footer"><span><b>Règlement</b> Espèces uniquement</span><span>Prix et disponibilité vérifiés par le serveur</span></footer>
      </div>
      <aside class="side-info"><p class="pos-kicker">À SAVOIR</p><h3>Un encaissement fiable, sans surprise.</h3><ul><li>Lots attribués selon la règle FEFO.</li><li>Le stock est décrémenté côté serveur.</li><li>Les paiements externes ne sont pas activés.</li></ul></aside>
    </section>
    <section class="ledger-grid" aria-label="Journaux de caisse">
      <div class="ledger-panel"><div class="ledger-heading"><div><p class="pos-kicker">JOURNAL</p><h2>Historique des ventes</h2></div><button class="text-action" :disabled="salesLoading" @click="loadSales(salesPage)">Actualiser</button></div>
        <p v-if="salesLoading" class="ledger-state" role="status">Chargement des ventes…</p><p v-else-if="salesUnavailable" class="ledger-state" role="status">Historique indisponible : l’API des ventes n’est pas accessible.</p><p v-else-if="salesError" class="ledger-state error-state" role="alert">Erreur de chargement des ventes : {{salesError}}</p><p v-else-if="!sales.length" class="ledger-state" role="status">Aucune vente enregistrée.</p>
        <div v-else class="ledger-rows"><article v-for="sale in sales" :key="sale.id" class="ledger-row"><div><strong>{{sale.receipt_number}}</strong><small>{{formatDate(sale.sold_at)}}<template v-if="sale.customer_name"> · {{sale.customer_name}}</template></small></div><span class="ledger-amount">{{money(sale.total)}}</span></article></div>
        <div v-if="salesMeta&&salesMeta.last_page>1" class="pager"><button class="text-action" :disabled="salesPage<=1||salesLoading" @click="loadSales(salesPage-1)">← Précédent</button><span>Page {{salesPage}} / {{salesMeta.last_page}}</span><button class="text-action" :disabled="salesPage>=salesMeta.last_page||salesLoading" @click="loadSales(salesPage+1)">Suivant →</button></div>
      </div>
      <div class="ledger-panel"><div class="ledger-heading"><div><p class="pos-kicker">MOUVEMENTS HORS VENTE</p><h2>Mouvements de caisse</h2></div><button v-if="permissions.canManageMovements&&movementCanWrite" class="pos-button primary small-button" :disabled="!session" @click="prepareMovement">＋ Ajouter</button></div>
        <p v-if="movementLoading" class="ledger-state" role="status">Chargement des mouvements…</p><p v-else-if="movementUnavailable" class="ledger-state" role="status">Mouvements indisponibles : l’API des mouvements n’est pas accessible.</p><p v-else-if="movementError" class="ledger-state error-state" role="alert">Erreur de chargement des mouvements : {{movementError}}</p><p v-else-if="!movements.length" class="ledger-state" role="status">Aucun mouvement enregistré.</p>
        <div v-else class="ledger-rows"><article v-for="movement in movements" :key="movement.id" class="ledger-row"><div><strong>{{categoryLabel[movement.category]}} · {{movement.direction==='entree'?'Entrée':'Sortie'}}</strong><small>{{formatDate(movement.occurred_at)}} · {{movement.reason}}</small></div><span class="ledger-amount" :class="movement.direction">{{movement.direction==='entree'?'+':'−'}}{{money(movement.amount)}}</span></article></div>
        <div v-if="movementMeta&&movementMeta.last_page>1" class="pager"><button class="text-action" :disabled="movementPage<=1||movementLoading" @click="loadMovements(movementPage-1)">← Précédent</button><span>Page {{movementPage}} / {{movementMeta.last_page}}</span><button class="text-action" :disabled="movementPage>=movementMeta.last_page||movementLoading" @click="loadMovements(movementPage+1)">Suivant →</button></div>
      </div>
    </section>
    <AppModal v-model="modal" :title="modalTitle" eyebrow="COMPTABILITÉ DE CAISSE" :busy="busy" size="wide">
      <form v-if="action==='sale'" id="pos-action" class="form-body pos-form" @submit.prevent="sell">
        <p v-if="dialogError" role="alert" class="pos-alert">{{dialogError}}</p>
        <p class="modal-intro">Ajoutez les produits à remettre au comptoir. Les prix applicables et les lots sont confirmés par le serveur.</p>
        <label>Client <span class="optional">Facultatif</span><input v-model="customer" maxlength="180" autocomplete="off" placeholder="Nom du client"/></label>
        <div class="line-heading"><strong>Produits</strong><span>{{cart.length}} ligne(s)</span></div>
        <div v-for="(item,index) in cart" :key="index" class="cart-row"><label class="product-field">Produit<select v-model.number="item.product_id" required><option :value="0" disabled>Choisir un produit…</option><option v-for="p in availableProducts" :key="p.id" :value="p.id">{{p.name}} · {{money(p.sale_price!)}} · {{p.available}} disponible(s)</option></select></label><label class="quantity-field">Qté<input v-model.number="item.quantite" type="number" min="1" step="1" required/></label><button v-if="cart.length>1" class="remove-line" type="button" :aria-label="`Retirer la ligne ${index+1}`" @click="cart.splice(index,1)">Retirer</button></div>
        <button class="add-line" type="button" @click="cart.push({product_id:0,quantite:1})">＋ Ajouter une ligne</button>
        <label>Montant reçu (FCFA)<input v-model.number="received" type="number" min="0" step="1" required inputmode="numeric" placeholder="0"/></label>
        <p class="payment-note">Paiement en espèces uniquement. Le montant total est calculé et confirmé par le serveur.</p>
        <div v-if="receipt" class="receipt-result" role="status"><strong>Vente enregistrée · reçu interne {{receipt.recu_interne}}</strong><span>Total {{money(receipt.montant_net_ttc)}} · Rendu {{money(receipt.monnaie_rendue)}}</span><small>Document interne non fiscal. Aucune intégration externe.</small></div>
      </form>
      <form v-else-if="action==='open'||action==='close'" id="pos-action" class="form-body pos-form" @submit.prevent="action==='open'?openSession():closeSession()">
        <p v-if="dialogError" role="alert" class="pos-alert">{{dialogError}}</p><p class="modal-intro">{{action==='open'?'Saisissez le fond réellement présent avant de démarrer les ventes.':'Saisissez le montant réellement compté. La clôture sera enregistrée par le serveur.'}}</p>
        <label>{{action==='open'?'Fond de caisse à l’ouverture':'Espèces comptées à la clôture'}} (FCFA)<input v-if="action==='open'" v-model.number="opening" type="number" min="0" step="1" required inputmode="numeric"/><input v-else v-model.number="closing" type="number" min="0" step="1" required inputmode="numeric"/></label>
      </form>
      <form v-else id="pos-action" class="form-body pos-form" @submit.prevent="createMovement">
        <p v-if="dialogError" role="alert" class="pos-alert">{{dialogError}}</p><p class="modal-intro">Enregistrez uniquement un mouvement réellement effectué. Il sera pris en compte dans le calcul de clôture.</p>
        <div class="movement-fields"><label>Sens<select v-model="movementForm.direction" required><option value="entree">Entrée d’espèces</option><option value="sortie">Sortie d’espèces</option></select></label><label>Motif détaillé<input v-model.trim="movementForm.reason" required minlength="3" maxlength="500" placeholder="Ex. apport de monnaie"/></label><label>Montant (FCFA)<input v-model.number="movementForm.amount" type="number" min="1" step="1" required inputmode="numeric"/></label><label>Catégorie<select v-model="movementForm.category" required><option v-for="category in movementCategories" :key="category" :value="category">{{categoryLabel[category]}}</option></select></label></div>
        <p class="payment-note">Les catégories proposées correspondent au sens choisi et sont validées par le serveur.</p>
      </form>
      <template #footer><button class="pos-button outlined" :disabled="busy" @click="modal=false">Annuler</button><button class="pos-button primary" :disabled="busy||!canSubmitAction" type="submit" form="pos-action">{{busy?'Enregistrement…':action==='sale'?'Encaisser en espèces':action==='open'?'Ouvrir la caisse':action==='close'?'Clôturer la caisse':'Enregistrer le mouvement'}}</button></template>
    </AppModal>
  </main>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import AppModal from '@/components/AppModal.vue'
import { request } from '@/services/quality'
type Product={id:number;name:string;sale_price:number|null;available:number}
type Session={id:number;opening_cash:number;cash_sales:number}
type SessionResponse={data:Session|null;can_sell?:boolean;can_manage_session?:boolean;can_manage_movements?:boolean}
type Receipt={recu_interne:string;montant_net_ttc:number;monnaie_rendue:number}
type Sale={id:number;receipt_number:string;customer_name:string|null;total:number;sold_at:string}
type Movement={id:number;direction:'entree'|'sortie';category:'apport'|'retrait'|'depense'|'remboursement'|'autre';reason:string;amount:number;occurred_at:string}
type Page<T>={data:T[];current_page:number;last_page:number;per_page:number;total:number;can_write?:boolean}
type Action='sale'|'open'|'close'|'movement'
const products=ref<Product[]>([]),session=ref<Session|null>(null),error=ref(''),notice=ref(''),busy=ref(false),apiState=ref('En attente')
const opening=ref(0),closing=ref(0),received=ref(0),customer=ref(''),cart=ref([{product_id:0,quantite:1}]),receipt=ref<Receipt|null>(null)
const modal=ref(false),action=ref<Action>('sale'),dialogError=ref(''),openKey=ref(''),closeKey=ref(''),saleKey=ref('')
const sales=ref<Sale[]>([]),movements=ref<Movement[]>([]),salesMeta=ref<Page<Sale>|null>(null),movementMeta=ref<Page<Movement>|null>(null),salesPage=ref(1),movementPage=ref(1),salesLoading=ref(false),movementLoading=ref(false),salesError=ref(''),movementError=ref(''),salesUnavailable=ref(false),movementUnavailable=ref(false),movementCanWrite=ref<boolean|null>(null),catalogError=ref('')
const permissions=ref<{canSell:boolean;canManageSession:boolean;canManageMovements:boolean}>({canSell:false,canManageSession:false,canManageMovements:false})
const movementForm=ref<{direction:'entree'|'sortie';category:Movement['category'];reason:string;amount:number}>({direction:'entree',category:'apport',reason:'',amount:1})
const categoryLabel:Record<Movement['category'],string>={apport:'Apport',retrait:'Retrait',depense:'Dépense',remboursement:'Remboursement',autre:'Autre'}
const movementCategories=computed<Movement['category'][]>(()=>movementForm.value.direction==='entree'?['apport','remboursement','autre']:['retrait','depense','autre'])
const availableProducts=computed(()=>products.value.filter(p=>p.sale_price!==null&&p.available>0))
const modalTitle=computed(()=>action.value==='sale'?'Nouvelle vente':action.value==='open'?'Ouvrir la caisse':action.value==='close'?'Clôturer la caisse':'Ajouter un mouvement de caisse')
const canSubmitAction=computed(()=>action.value==='sale'?permissions.value.canSell&&!!session.value&&!catalogError.value:action.value==='open'||action.value==='close'?permissions.value.canManageSession:permissions.value.canManageMovements&&movementCanWrite.value===true&&!!session.value)
function newKey(){return crypto.randomUUID()}
function money(value:number){return `${new Intl.NumberFormat('fr-FR').format(value)} FCFA`}
function formatDate(value:string){return new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(value))}
watch(()=>movementForm.value.direction,direction=>{movementForm.value.category=direction==='entree'?'apport':'depense'})
watch([cart,received,customer],()=>{saleKey.value='';receipt.value=null},{deep:true})
async function refresh(){const [c,s]=await Promise.allSettled([request<{data:Product[]}>('/ventescaisse/catalog'),request<SessionResponse>('/ventescaisse/sessions/active')]);if(c.status==='fulfilled'){products.value=c.value.data;catalogError.value=''}else{products.value=[];catalogError.value=c.reason instanceof Error?c.reason.message:'Erreur de lecture du catalogue.'}if(s.status==='fulfilled'){session.value=s.value.data;permissions.value={canSell:s.value.can_sell===true,canManageSession:s.value.can_manage_session===true,canManageMovements:s.value.can_manage_movements===true};apiState.value='Connectée';if(typeof s.value.can_sell!=='boolean'||typeof s.value.can_manage_session!=='boolean'||typeof s.value.can_manage_movements!=='boolean')error.value='Les droits de caisse sont absents de la réponse API ; les actions sont bloquées.'}else{session.value=null;permissions.value={canSell:false,canManageSession:false,canManageMovements:false};apiState.value='Indisponible';error.value=s.reason instanceof Error?s.reason.message:'Lecture des droits de caisse impossible.'}}
async function load(){error.value='';await refresh()}
function unavailable(e:unknown){return e instanceof Error&&/404|not found|introuvable/i.test(e.message)}
async function loadSales(page=1){salesLoading.value=true;salesError.value='';salesUnavailable.value=false;try{const result=await request<Page<Sale>>(`/ventescaisse/sales?per_page=8&page=${page}`);sales.value=result.data;salesMeta.value=result;salesPage.value=result.current_page}catch(e){sales.value=[];salesMeta.value=null;salesUnavailable.value=unavailable(e);if(!salesUnavailable.value)salesError.value=e instanceof Error?e.message:'Erreur inconnue.'}finally{salesLoading.value=false}}
async function loadMovements(page=1){movementLoading.value=true;movementError.value='';movementUnavailable.value=false;movementCanWrite.value=null;try{const result=await request<Page<Movement>>(`/ventescaisse/cash-movements?per_page=8&page=${page}`);movements.value=result.data;movementMeta.value=result;movementPage.value=result.current_page;if(typeof result.can_write==='boolean')movementCanWrite.value=result.can_write;else movementError.value='Le droit can_write est absent de la réponse API ; les actions sont bloquées.'}catch(e){movements.value=[];movementMeta.value=null;movementUnavailable.value=unavailable(e);if(!movementUnavailable.value)movementError.value=e instanceof Error?e.message:'Erreur inconnue.'}finally{movementLoading.value=false}}
function prepareMovement(){if(!canSubmitAction.value)return;action.value='movement';dialogError.value='';error.value='';notice.value='';movementForm.value={direction:'entree',category:'apport',reason:'',amount:1};modal.value=true}
function prepareSession(kind:'open'|'close'){if(!permissions.value.canManageSession)return;action.value=kind;dialogError.value='';error.value='';notice.value='';if(kind==='open'&&!openKey.value)openKey.value=newKey();if(kind==='close'&&!closeKey.value)closeKey.value=newKey();modal.value=true}
function startSale(){if(!session.value||!permissions.value.canSell||catalogError.value)return;action.value='sale';dialogError.value='';error.value='';notice.value='';receipt.value=null;cart.value=[{product_id:0,quantite:1}];customer.value='';received.value=0;saleKey.value='';modal.value=true}
async function openSession(){if(!canSubmitAction.value)return;busy.value=true;dialogError.value='';if(!openKey.value)openKey.value=newKey();try{session.value=(await request<{data:Session}>('/ventescaisse/sessions','POST',{opening_cash:opening.value,request_key:openKey.value})).data;openKey.value='';modal.value=false;notice.value='Caisse ouverte.';apiState.value='Connectée';void refresh()}catch(e){dialogError.value=e instanceof Error?e.message:'Ouverture impossible.'}finally{busy.value=false}}
async function closeSession(){if(!session.value||!canSubmitAction.value)return;busy.value=true;dialogError.value='';if(!closeKey.value)closeKey.value=newKey();try{await request(`/ventescaisse/sessions/${session.value.id}/close`,'POST',{closing_cash:closing.value,request_key:closeKey.value});session.value=null;closeKey.value='';modal.value=false;notice.value='Caisse clôturée.';void refresh()}catch(e){dialogError.value=e instanceof Error?e.message:'Clôture impossible.'}finally{busy.value=false}}
async function sell(){if(!session.value||!canSubmitAction.value)return;busy.value=true;dialogError.value='';if(!saleKey.value)saleKey.value=newKey();try{receipt.value=(await request<{data:Receipt}>('/ventescaisse/sales','POST',{request_key:saleKey.value,mode_reglement:'especes',montant_recu:received.value,client_nom:customer.value||undefined,lignes:cart.value.map(x=>({product_id:x.product_id,quantite:x.quantite}))})).data;saleKey.value='';modal.value=false;notice.value=`Vente enregistrée · reçu interne ${receipt.value.recu_interne}. Document non fiscal.`;void Promise.all([refresh(),loadSales(1),loadMovements(1)])}catch(e){dialogError.value=e instanceof Error?e.message:'Vente impossible.'}finally{busy.value=false}}
async function createMovement(){if(!session.value||!canSubmitAction.value)return;busy.value=true;dialogError.value='';try{await request<{data:Movement}>('/ventescaisse/cash-movements','POST',movementForm.value);await Promise.all([loadMovements(1),loadSales(salesPage.value),refresh()]);modal.value=false;notice.value='Mouvement de caisse enregistré.'}catch(e){dialogError.value=e instanceof Error?e.message:'Enregistrement du mouvement impossible.'}finally{busy.value=false}}
onMounted(()=>{void load();void loadSales();void loadMovements()})
</script>

<style scoped>
.pos-page{--forest:#023010;--deep:#0f3b27;--action:#18aa38;--lime:#92ff5f;--line:#cfe3d5;--soft:#cff1d2;--paper:#f7f9f7;--ink:#1f2420;--muted:#5c6660;max-width:1260px;margin:0 auto;padding:32px clamp(16px,4vw,52px) 56px;color:var(--ink);font-family:inherit}.pos-header{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:0 0 25px;border-bottom:1px solid var(--line)}.pos-kicker{font-size:11px;letter-spacing:.14em;font-weight:800;color:var(--deep);margin:0 0 8px}.pos-kicker span{color:var(--action)}h1{font-size:clamp(32px,4vw,48px);letter-spacing:-.045em;line-height:1.05;margin:0;color:var(--forest)}h1 em{font-style:normal;color:var(--action)}.pos-subtitle{margin:9px 0 0;color:var(--muted)}.header-status{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--muted);flex-wrap:wrap;justify-content:flex-end}.header-status strong{color:var(--deep)}.live-dot{width:9px;height:9px;border-radius:50%;background:var(--action);box-shadow:0 0 0 4px #18aa3820}.receipt-note{border-left:1px solid var(--line);padding-left:14px;margin-left:8px;color:var(--deep);font-weight:700}.session-band{display:grid;grid-template-columns:minmax(180px,1fr) 2fr auto;align-items:center;gap:24px;padding:22px 24px;margin:24px 0;background:var(--forest);color:#fff;border-radius:13px;box-shadow:0 10px 28px #02301018}.session-mark{display:flex;align-items:center;gap:14px}.session-mark>span{font-size:23px;font-weight:800;color:var(--lime);border-right:1px solid #ffffff3b;padding-right:14px}.session-mark .pos-kicker{color:#a5d8af;margin-bottom:5px}.session-mark h2{font-size:18px;margin:0}.session-facts{display:flex;gap:clamp(15px,3vw,45px)}.session-facts>div{display:grid;gap:7px}.session-facts small{font-size:10px;letter-spacing:.1em;color:#afd0b6}.session-facts strong{font-size:14px;white-space:nowrap}.session-facts i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:8px;background:#92ff5f}.session-facts i.is-closed{background:#ffad63}.pos-button{min-height:48px;padding:0 18px;border-radius:7px;border:1px solid transparent;font:700 14px inherit;cursor:pointer;transition:transform .16s,background .16s,border .16s}.pos-button:hover:not(:disabled){transform:translateY(-1px)}.pos-button:focus-visible,.add-line:focus-visible,.remove-line:focus-visible{outline:3px solid #92ff5f;outline-offset:3px}.pos-button:disabled{opacity:.48;cursor:not-allowed}.pos-button span{padding-left:15px;font-size:18px}.pos-button.primary{background:var(--action);color:#fff}.pos-button.primary:hover:not(:disabled){background:#12852d}.pos-button.outlined{background:transparent;color:var(--deep);border-color:var(--line)}.session-band .outlined{color:#fff;border-color:#ffffff85}.session-band .outlined:hover{background:#ffffff14}.pos-button.dark{background:var(--forest);color:#fff}.workspace{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(245px,.8fr);gap:20px}.sale-panel{min-height:390px;background:#fff;border:1px solid var(--line);border-radius:13px;overflow:hidden}.sale-heading{padding:22px 25px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--soft);gap:12px}.sale-heading .pos-kicker{margin-bottom:5px}.sale-heading h2{font-size:23px;letter-spacing:-.03em;margin:0;color:var(--forest)}.sale-body{min-height:255px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:25px}.cart-symbol{width:48px;height:48px;display:grid;place-items:center;border-radius:14px;background:#e8f8e9;color:var(--deep);font-size:26px;font-weight:400}.sale-body h3{margin:15px 0 3px;color:var(--forest);font-size:19px}.sale-body p{margin:0 0 18px;color:var(--muted);max-width:390px;line-height:1.55}.sale-footer{display:flex;justify-content:space-between;gap:12px;padding:14px 24px;background:var(--paper);border-top:1px solid var(--soft);font-size:12px;color:var(--muted)}.sale-footer b{color:var(--deep);margin-right:5px}.side-info{background:#edf6ee;border-radius:13px;paddi